def backfill_custom_fields(apps, schema_editor):
    """Mark only fields that differ from the company row as customised.

    Previously an override flag froze the whole section; now uncustomised
    fields track the company value, so only real differences are recorded.
    """
    ShopPosSettings = apps.get_model("shops", "ShopPosSettings")
    CompanyPosSettings = apps.get_model("shops", "CompanyPosSettings")
    company = CompanyPosSettings.objects.filter(pk=1).first()
    if company is None:
        return
    for row in ShopPosSettings.objects.all().iterator():
        updates = {}
        if row.override_pos:
            updates["custom_pos_fields"] = [
                name
                for name in SHOP_POS_FIELD_NAMES
                if getattr(row, name, None) != getattr(company, name, None)
            ]
        if row.override_receipt:
            updates["custom_receipt_fields"] = [
                name
                for name in SHOP_RECEIPT_FIELD_NAMES
                if getattr(row, name, None) != getattr(company, name, None)
            ]
        if updates:
            ShopPosSettings.objects.filter(pk=row.pk).update(**updates)


